const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-wis-timestamp'] || '');
const signature = String(headers['x-wis-signature'] || '');
const secret = $env.WIS_WEBHOOK_SECRET;
if (!secret || !/^\d+$/.test(timestamp) || Math.abs(Date.now()/1000 - Number(timestamp)) > 300) throw new Error('Webhook no autorizado');
let raw;
if (item.binary?.data) raw = await this.helpers.getBinaryDataBuffer(0, 'data');
else if (typeof item.json.body === 'string') raw = Buffer.from(item.json.body);
else if (item.json.body?.type === 'Buffer' && Array.isArray(item.json.body.data)) raw = Buffer.from(item.json.body.data);
else throw new Error('Se requiere Raw Body; no verificar JSON reserializado');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.').update(raw).digest('hex');
const a = Buffer.from(signature), b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a,b)) throw new Error('Firma inválida');
const event = JSON.parse(raw.toString('utf8'));
if (event.id !== headers['x-wis-event-id']) throw new Error('Identificador inválido');
// No agregar envíos aquí sin deduplicación durable por event.id.
return [{json:{verified:true,event_id:event.id,event_type:event.type}}];
